import {
  useState,
  type CSSProperties,
  type PointerEvent,
  type ReactNode,
} from "react";
import "./Folder.css";

export interface FolderProps {
  color?: string;
  size?: number;
  items?: ReactNode[];
  className?: string;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

function darkenColor(hex: string, percent: number) {
  let color = hex.startsWith("#") ? hex.slice(1) : hex;
  if (color.length === 3) {
    color = color
      .split("")
      .map((character) => character + character)
      .join("");
  }
  const number = Number.parseInt(color.slice(0, 6), 16);
  const red = (number >> 16) & 0xff;
  const green = (number >> 8) & 0xff;
  const blue = number & 0xff;
  const reduce = (channel: number) =>
    Math.max(0, Math.min(255, Math.floor(channel * (1 - percent))));
  return `#${((1 << 24) + (reduce(red) << 16) + (reduce(green) << 8) + reduce(blue))
    .toString(16)
    .slice(1)
    .toUpperCase()}`;
}

export default function Folder({
  color = "#857fa8",
  size = 1,
  items = [],
  className = "",
  defaultOpen = false,
  onOpenChange,
}: FolderProps) {
  const papers = [...items.slice(0, 3)];
  while (papers.length < 3) papers.push(null);
  const [open, setOpen] = useState(defaultOpen);
  const [paperOffsets, setPaperOffsets] = useState(
    Array.from({ length: 3 }, () => ({ x: 0, y: 0 })),
  );

  const toggle = () => {
    setOpen((current) => {
      const next = !current;
      if (!next) {
        setPaperOffsets(Array.from({ length: 3 }, () => ({ x: 0, y: 0 })));
      }
      onOpenChange?.(next);
      return next;
    });
  };

  const movePaper = (
    event: PointerEvent<HTMLDivElement>,
    index: number,
  ) => {
    if (!open) return;
    const rect = event.currentTarget.getBoundingClientRect();
    setPaperOffsets((current) => {
      const next = [...current];
      next[index] = {
        x: (event.clientX - (rect.left + rect.width / 2)) * 0.15,
        y: (event.clientY - (rect.top + rect.height / 2)) * 0.15,
      };
      return next;
    });
  };

  return (
    <div
      className={`folder ${className}`.trim()}
      style={
        {
          "--folder-color": color,
          "--folder-back-color": darkenColor(color, 0.08),
          "--paper-1": darkenColor("#ffffff", 0.1),
          "--paper-2": darkenColor("#ffffff", 0.05),
          "--paper-3": "#ffffff",
          "--folder-scale": size,
        } as CSSProperties
      }
    >
      <div
        className={`folder__body${open ? " open" : ""}`}
        onClick={(event) => {
          if ((event.target as HTMLElement).closest("button")) return;
          toggle();
        }}
        onKeyDown={(event) => {
          if (event.key !== "Enter" && event.key !== " ") return;
          event.preventDefault();
          toggle();
        }}
        tabIndex={0}
        role="button"
        aria-expanded={open}
        aria-label={open ? "Close folder" : "Open folder"}
      >
        <div className="folder__back">
          {papers.map((item, index) => (
            <div
              key={index}
              className={`paper paper-${index + 1}`}
              onPointerMove={(event) => movePaper(event, index)}
              onPointerLeave={() =>
                setPaperOffsets((current) => {
                  const next = [...current];
                  next[index] = { x: 0, y: 0 };
                  return next;
                })
              }
              style={
                open
                  ? {
                      "--magnet-x": `${paperOffsets[index]?.x ?? 0}px`,
                      "--magnet-y": `${paperOffsets[index]?.y ?? 0}px`,
                    } as CSSProperties
                  : undefined
              }
            >
              {item}
            </div>
          ))}
          <div className="folder__front" />
          <div className="folder__front right" />
        </div>
      </div>
    </div>
  );
}
