export const REMOVED_READING_IDS = [
  "jane-eyre",
  "dracula",
  "oliver-twist",
  "three-musketeers",
] as const;

const KNOWLEDGE_BY_CORE_BOOK: Record<string, string> = {
  "core-language": "knowledge-linguistics",
  "core-literature": "knowledge-literature",
  "core-culture": "knowledge-culture",
  "core-translation": "knowledge-translation",
  "core-writing": "knowledge-writing",
  "core-lexicology": "knowledge-vocabulary",
};

export function shelfBookDestination(id: string) {
  const base = id.split("#")[0] ?? id;
  const knowledgeBook = KNOWLEDGE_BY_CORE_BOOK[base];
  if (knowledgeBook) return `/book/${knowledgeBook}`;
  if (base === "vocabulary") return "/vocabulary";
  if (base === "commonplace") return "/corpus";
  if (base === "notebook-index") return "/library";
  return `/book/${base}`;
}
