import type { WordStudyPlan } from "@inkflow/shared";
import { createId } from "./createId";

export const WORD_STUDY_PLAN_STORAGE_KEY = "inkflow:word-study-plan:v1";

export function createWordStudyPlan(
  wordIds: string[],
  dailyNewLimit: number,
  sourceBookIds: string[] = [],
  sourceModuleIds: string[] = [],
): WordStudyPlan {
  const now = new Date().toISOString();
  return {
    id: `word-plan-${createId()}`,
    wordIds: [...new Set(wordIds)],
    dailyNewLimit,
    sourceBookIds,
    sourceModuleIds,
    createdAt: now,
    updatedAt: now,
  };
}

export function loadWordStudyPlan(): WordStudyPlan | null {
  if (typeof localStorage === "undefined") return null;
  try {
    const parsed = JSON.parse(
      localStorage.getItem(WORD_STUDY_PLAN_STORAGE_KEY) ?? "null",
    ) as WordStudyPlan | null;
    if (!parsed || !Array.isArray(parsed.wordIds)) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function saveWordStudyPlan(plan: WordStudyPlan | null) {
  if (typeof localStorage === "undefined") return;
  try {
    if (plan) {
      localStorage.setItem(WORD_STUDY_PLAN_STORAGE_KEY, JSON.stringify(plan));
    } else {
      localStorage.removeItem(WORD_STUDY_PLAN_STORAGE_KEY);
    }
  } catch {
    // Storage is best-effort; the in-memory plan still works for this session.
  }
}

export function buildDailyWordQueue(
  words: Array<{ id: string; nextReviewAt: string }>,
  plan: WordStudyPlan,
  now = Date.now(),
) {
  const byId = new Map(words.map((word) => [word.id, word]));
  const selected = plan.wordIds
    .map((id) => byId.get(id))
    .filter((word) => word !== undefined);
  const due = selected.filter(
    (word) => new Date(word.nextReviewAt).getTime() <= now,
  );
  const fresh = selected.filter(
    (word) => new Date(word.nextReviewAt).getTime() > now,
  );
  return [
    ...due.map((word) => word.id),
    ...fresh.slice(0, plan.dailyNewLimit).map((word) => word.id),
  ];
}
