import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { App } from "./app";
import { MotionSystem } from "./motion/MotionSystem";
import { initializeTheme } from "./store/theme";
import "./styles.css";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000,
      retry: 1,
    },
  },
});

initializeTheme();

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        <MotionSystem>
          <App />
        </MotionSystem>
      </BrowserRouter>
    </QueryClientProvider>
  </StrictMode>,
);

// Lift the boot shell (see index.html) once React has actually committed a
// frame — the intro curtain sits at the same palette underneath, so the
// handoff is a cross-fade between two identical surfaces, not a flash.
requestAnimationFrame(() => {
  requestAnimationFrame(() => {
    const bootShell = document.getElementById("boot-shell");
    if (!bootShell) return;
    bootShell.classList.add("is-dismissed");
    window.setTimeout(() => bootShell.remove(), 460);
  });
});

if (import.meta.env.PROD && "serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    void navigator.serviceWorker.register("/sw.js");
  });
}
